def shortest_edit_script(a: list[str], b: list[str]) -> list[tuple]:
    n, m = len(a), len(b)
    if n == 0 and m == 0:
        return []

    if n + m <= 600:
        # Full O(n*m) dynamic programming
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for j in range(m + 1):
            dp[n][j] = m - j
        for i in range(n + 1):
            dp[i][m] = n - i
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                best = min(1 + dp[i + 1][j], 1 + dp[i][j + 1])
                if a[i] == b[j] and dp[i + 1][j + 1] < best:
                    best = dp[i + 1][j + 1]
                dp[i][j] = best

        result = []
        i, j = 0, 0
        while i < n or j < m:
            if i < n and j < m and a[i] == b[j] and dp[i + 1][j + 1] == dp[i][j]:
                result.append(("=", i, j))
                i += 1
                j += 1
            elif i < n and 1 + dp[i + 1][j] == dp[i][j]:
                result.append(("-", i))
                i += 1
            else:
                result.append(("+", j))
                j += 1
        return result
    else:
        # Band-limited DP: edit distance guaranteed <= 100
        E_MAX = 100
        INF = float('inf')
        dp = {}
        dp[(n, m)] = 0

        for i in range(n, -1, -1):
            j_lo = max(0, n - m - E_MAX + i)
            j_hi = min(m, n - m + E_MAX + i)
            for j in range(j_hi, j_lo - 1, -1):
                if i == n and j == m:
                    continue
                best = INF
                diff = (n - i) - (m - j)

                if i < n and j < m and a[i] == b[j]:
                    v = dp.get((i + 1, j + 1))
                    if v is not None and v < best:
                        best = v

                if i < n and diff > -E_MAX:
                    v = dp.get((i + 1, j))
                    if v is not None and v + 1 < best:
                        best = v + 1

                if j < m and diff < E_MAX:
                    v = dp.get((i, j + 1))
                    if v is not None and v + 1 < best:
                        best = v + 1

                dp[(i, j)] = best

        result = []
        i, j = 0, 0
        while i < n or j < m:
            cur = dp[(i, j)]
            if i < n and j < m and a[i] == b[j]:
                v = dp.get((i + 1, j + 1))
                if v is not None and v == cur:
                    result.append(("=", i, j))
                    i += 1
                    j += 1
                    continue
            if i < n:
                v = dp.get((i + 1, j))
                if v is not None and v + 1 == cur:
                    result.append(("-", i))
                    i += 1
                    continue
            result.append(("+", j))
            j += 1
        return result
